import{_ as r,r as l,o as d,c as s,e as o,a as t,s as i}from"./chunks/framework.CXcwiNg-.js";const v=JSON.parse('{"title":"目录结构 - October CMS - 3.x","titleTemplate":false,"description":"了解 October CMS 根目录中每个目录的用途","frontmatter":{"subtitle":"了解 October CMS 根目录中每个目录的用途"},"headers":[{"level":2,"title":"根目录","slug":"根目录","link":"#根目录","children":[{"level":3,"title":"App 目录","slug":"app-目录","link":"#app-目录","children":[]},{"level":3,"title":"引导程序目录","slug":"引导程序目录","link":"#引导程序目录","children":[]},{"level":3,"title":"配置目录","slug":"配置目录","link":"#配置目录","children":[]},{"level":3,"title":"插件目录","slug":"插件目录","link":"#插件目录","children":[]},{"level":3,"title":"存储目录","slug":"存储目录","link":"#存储目录","children":[]},{"level":3,"title":"模块目录","slug":"模块目录","link":"#模块目录","children":[]},{"level":3,"title":"主题目录","slug":"主题目录","link":"#主题目录","children":[]},{"level":3,"title":"供应商目录","slug":"供应商目录","link":"#供应商目录","children":[]}]},{"level":2,"title":"App 目录","slug":"app-目录-1","link":"#app-目录-1","children":[{"level":3,"title":"Assets 目录","slug":"assets-目录","link":"#assets-目录","children":[]},{"level":3,"title":"Blueprints 目录","slug":"blueprints-目录","link":"#blueprints-目录","children":[]},{"level":3,"title":"其他目录","slug":"其他目录","link":"#其他目录","children":[]}]}],"relativePath":"3.x/zh-cn/setup/directory-structure.md","filePath":"3.x/zh-cn/setup/directory-structure.md"}'),p={name:"3.x/zh-cn/setup/directory-structure.md"};function h(n,e,u,m,_,f){const c=l("pre-heading"),a=l("post-heading");return d(),s("div",null,[o(c),e[0]||(e[0]=t("h1",null,"目录结构",-1)),o(a),e[1]||(e[1]=i('<p>October CMS 使用模块化结构，大多数编程功能都位于模块目录或插件目录中。</p><h2 id="根目录"><a href="#根目录" class="header-anchor">#</a> 根目录</h2><h3 id="app-目录"><a href="#app-目录" class="header-anchor">#</a> App 目录</h3><p><code>app</code> 目录包含应用程序特定的代码。该目录的内容将在本节之后详细介绍。简而言之，此区域包含不属于传统插件的业务逻辑。大多数插件功能在此目录中也可以使用。</p><h3 id="引导程序目录"><a href="#引导程序目录" class="header-anchor">#</a> 引导程序目录</h3><p><code>bootstrap</code> 目录包含加载 Laravel 框架的 app.php 引导脚本。该目录还包含自定义的 PHP 类自动加载器。通常情况下，不应修改此目录中的文件。</p><h3 id="配置目录"><a href="#配置目录" class="header-anchor">#</a> 配置目录</h3><p><code>config</code> 目录包含所有应用程序配置文件。每个文件控制应用程序的运行方式。配置文件可以根据您的应用程序需求进行修改。系统更新不会修改配置文件。</p><h3 id="插件目录"><a href="#插件目录" class="header-anchor">#</a> 插件目录</h3><p><code>plugins</code> 目录包含扩展 October CMS 核心功能的包。插件可以通过引入新功能来修改平台。默认情况下，系统会加载文件系统中找到的所有插件。可以使用 <code>system.disable_plugins</code> 配置参数禁用特定的插件。</p><h3 id="存储目录"><a href="#存储目录" class="header-anchor">#</a> 存储目录</h3><p><code>storage</code> 目录包含日志文件、缓存文件、会话以及 October CMS 生成的其他文件。它包含以下几个子目录：</p><ul><li><code>app</code> - 包含应用程序特定的存储文件，例如媒体文件、文件上传和自动生成的资源（如调整大小后的文件和合并的资源文件）。</li><li><code>framework</code> - 由 Laravel 框架用于存储其生成的文件和缓存。</li><li><code>cms</code> - 由 October CMS 平台用于存储其生成的文件和缓存。</li><li><code>logs</code> - 包含应用程序的日志文件。</li><li><code>temp</code> - 用于存储临时的应用程序文件。</li></ul><h3 id="模块目录"><a href="#模块目录" class="header-anchor">#</a> 模块目录</h3><p><code>modules</code> 目录包含 October CMS 的核心包，提供系统中通用的核心功能。默认情况下，模块根据其在文件系统中的存在情况自动加载。但是，也可以通过 <code>system.load_modules</code> 配置参数指定要加载哪些模块。<code>system</code> 模块是应用程序运行所必需的最低要求。</p><ul><li><code>system</code> - 定义 October CMS 的核心功能，是一个必需的模块。</li><li><code>cms</code> - 引入用于渲染前端网站主题的功能。它负责将请求路由到页面、渲染页面和处理 AJAX 请求。</li><li><code>backend</code> - 负责显示后台面板页面。</li><li><code>editor</code> - 引入用于在后台面板中编辑 CMS 模板的用户界面。</li><li><code>media</code> - 引入后台面板中的媒体文件管理用户界面。它允许后台用户上传媒体文件（如图片或视频文件），并将其包含在其他位置（例如博客文章中）。</li><li><code>tailor</code> - 引入 October CMS Tailor 功能。</li></ul><h3 id="主题目录"><a href="#主题目录" class="header-anchor">#</a> 主题目录</h3><p><code>themes</code> 目录包含前端网站 CMS 主题的子目录。CMS 主题包括网站页面、布局、部件、资源和其他文件的模板文件。活动主题通过 <code>cms.active_theme</code> 配置参数设置，并可以在后台面板设置页面中进行覆盖。</p><h3 id="供应商目录"><a href="#供应商目录" class="header-anchor">#</a> 供应商目录</h3><p><code>vendor</code> 目录包含通过 Composer 引入的包。一些插件也可能包含 vendor 目录。系统的 vendor 目录优先于插件特定的 vendor 目录。</p><h2 id="app-目录-1"><a href="#app-目录-1" class="header-anchor">#</a> App 目录</h2><p><code>app</code> 目录包含应用程序特定的文件，包括内容、资源和不属于<a href="./../extend/system/plugins.html">传统插件</a>的业务逻辑。它包含一个由默认配置加载的 Service Provider 文件。</p><h3 id="assets-目录"><a href="#assets-目录" class="header-anchor">#</a> Assets 目录</h3><p><code>app/assets</code> 目录包含资源文件，例如 JavaScript、CSS 和图片文件。此目录应该对网站公开可访问。</p><h3 id="blueprints-目录"><a href="#blueprints-目录" class="header-anchor">#</a> Blueprints 目录</h3><p><code>app/blueprints</code> 目录包含 Tailor 使用的<a href="./../cms/tailor/introduction.html">内容蓝图</a>文件。</p><h3 id="其他目录"><a href="#其他目录" class="header-anchor">#</a> 其他目录</h3><p>您可以在此处创建任何目录，就像插件一样，例如 <code>models</code> 或 <code>controllers</code>。这些目录将在 <code>App</code> 命名空间中自动加载。例如，文件 <strong>app/models/Customer.php</strong> 在 PHP 中将以 <code>App\\Models\\Customer</code> 的形式使用。</p>',28))])}const S=r(p,[["render",h]]);export{v as __pageData,S as default};
